var t=`0546-harees`;var n=`world-0546`;var a=`AE`;var s=`western-asia`;var r=4;var o=173;var h={en:`Harees`,ua:`Харіс`};var l={en:`A traditional dish from United Arab Emirates, centered on wheat berries, chicken thigh. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Об'єднані Арабські Емірати. Основні складники: зерна пшениці, куряче стегно. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 150 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 150 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:150,i:[[`wheat-berries`,410,`g`],[`chicken-thigh`,850,`g`],[`water`,1600,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Beat or mash the fully cooked wheat and chicken until the mixture becomes thick, smooth and porridge-like; adjust with hot cooking liquid.`,ua:`Розтирайте або збивайте готові пшеницю та курятину, доки суміш не стане густою та однорідною, мов каша; за потреби додайте гарячий відвар.`,t:[`mixing`],m:20,i:[[`unsalted-butter`,75,`g`],[`ground-cinnamon`,3,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`extra-virgin-olive-oil`,25,`ml`]]}];var g={slug:t,id:n,country:`AE`,region:s,servings:4,minutes:173,title:h,text:l,steps:d};export{a as country,g as default,n as id,o as minutes,s as region,r as servings,t as slug,d as steps,l as text,h as title};